    @classmethod
    def _create_input_socket(
        cls,
        value: tuple = (0, 0, 0),
        name: str = 'Rotation',
        tip: str = '',
        panel: str = '',
        default_input: VALUE = 'VALUE',
        force_non_field: bool = False,
        hide_in_modifier: bool = False,
        hide_value: bool = False,
        is_panel_toggle: bool = False,
        layer_selection: bool = False,
        menu_expanded: bool = False,
        optional_label: bool = False,
        shape: Literal['AUTO', 'DYNAMIC', 'FIELD', 'LIST', 'SINGLE'] = 'AUTO',
    ):
        """Create a Rotation input with subtype NONE.

        Parameters
        ----------
        value : tuple, optional
            Default value. Default: (0, 0, 0).
        name : str, optional
            Input socket name. Default: 'Rotation'.
        tip : str, optional
            Property description. Default: ''.
        panel : str, optional
            Panel name. Default: ''.
        default_input : VALUE, optional
            Property default_input. Default: 'VALUE'.
        force_non_field : bool, optional
            Property force_non_field. Default: False.
        hide_in_modifier : bool, optional
            Property hide_in_modifier. Default: False.
        hide_value : bool, optional
            Property hide_value. Default: False.
        is_panel_toggle : bool, optional
            Property is_panel_toggle. Default: False.
        layer_selection : bool, optional
            Property layer_selection_field. Default: False.
        menu_expanded : bool, optional
            Property menu_expanded. Default: False.
        optional_label : bool, optional
            Property optional_label. Default: False.
        shape : Literal['AUTO', 'DYNAMIC', 'FIELD', 'LIST', 'SINGLE'], optional
            Property structure_type. Default: 'AUTO'.

        Returns
        -------
        Rotation
            Input socket.
        """
        from ...root.tree import Tree
        value = utils.python_value_for_socket(value, cls.SOCKET_TYPE)
        return Tree.current_tree().create_input_socket(
            'NodeSocketRotation',
            default_value=value,
            name=name,
            tip=tip,
            panel=panel,
            default_input=default_input,
            force_non_field=force_non_field,
            hide_in_modifier=hide_in_modifier,
            hide_value=hide_value,
            is_panel_toggle=is_panel_toggle,
            layer_selection=layer_selection,
            menu_expanded=menu_expanded,
            optional_label=optional_label,
            shape=shape,
        )

